begin;
-- Disposable fixtures and synthetic strokes only; all evidence and notifications roll back.
create function pg_temp.qa_change_signature_observation(p_id uuid) returns void language sql security definer set search_path='' as $$update public.field_observations set description='[QA rollback] Changed after signature' where id=p_id$$;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where active and personnel_category='ceo' limit 1),true);
set local role authenticated;
do $$
declare op uuid;supervisor uuid;manager uuid;ceo uuid;outsider uuid;unit uuid;asset uuid;obs uuid;task uuid;sig uuid;sig2 uuid;key uuid;ctx jsonb;hash text;draw jsonb;bad boolean;before_status text;before_activity bigint;cursor_id bigint;old_snapshot jsonb;
begin
 select ceo_user_id into ceo from public.task_governance;
 select id,corporate_manager_id into strict op,supervisor from public.profiles where active and role='operator' and full_name not like '[MOC]%' order by created_at limit 1;
 select corporate_manager_id into manager from public.profiles where id=supervisor;
 select id into outsider from public.profiles where active and role='operator' and id<>op order by created_at limit 1;
 select a.business_unit_id,a.id into unit,asset from public.assets a join public.user_unit_access u on u.business_unit_id=a.business_unit_id where u.user_id=op and a.status='active' limit 1;
 select jsonb_build_array(jsonb_agg(jsonb_build_array((.1+i*.025)::numeric, (.4+sin(i::double precision)*.1)::numeric) order by i)) into draw from generate_series(0,20) i;
 perform set_config('request.jwt.claim.sub',op::text,true);
 obs:=(public.submit_field_observation(gen_random_uuid(),unit,asset,'equipment','[QA rollback] Signature observation','normal')->>'observation_id')::uuid;
 ctx:=public.record_signature_context('observation',obs);hash:=ctx->>'snapshot_hash';if not (ctx->>'can_sign')::boolean then raise exception 'Reporter cannot sign';end if;
 if jsonb_array_length(ctx->'signatures')<>0 then raise exception 'New record unexpectedly has a signature';end if;
 bad:=false;begin perform public.add_record_signature('observation',obs,op,hash,'[]','',gen_random_uuid(),true);exception when raise_exception then bad:=true;end;if not bad then raise exception 'Blank signature accepted';end if;
 bad:=false;begin perform public.add_record_signature('observation',obs,supervisor,hash,draw,'',gen_random_uuid(),true);exception when raise_exception then bad:=true;end;if not bad then raise exception 'Forged signer accepted';end if;
 bad:=false;begin perform public.add_record_signature('observation',obs,op,hash,draw,'',gen_random_uuid(),false);exception when raise_exception then bad:=true;end;if not bad then raise exception 'Consent bypass accepted';end if;
 key:=gen_random_uuid();sig:=public.add_record_signature('observation',obs,op,hash,draw,'My observation',key,true);
 if public.add_record_signature('observation',obs,op,hash,draw,'My observation',key,true)<>sig then raise exception 'Retry duplicated signature';end if;
 if public.add_record_signature('observation',obs,op,hash,draw,'Duplicate revision',gen_random_uuid(),true)<>sig then raise exception 'Same person signed same revision twice';end if;
 bad:=false;begin perform public.add_record_signature('observation',obs,op,hash,draw,'Changed retry',key,true);exception when raise_exception then bad:=true;end;if not bad then raise exception 'Retry key accepts changed data';end if;
 if (select status from public.field_observations where id=obs)<>'submitted' then raise exception 'Signature changed observation status';end if;
 if exists(select 1 from public.observation_ai_memory where observation_id=obs) then raise exception 'Signature admitted report into AI';end if;
 select snapshot into old_snapshot from public.record_signatures where id=sig;
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 if not exists(select 1 from public.record_signatures where id=sig and signer_id=op and signer_name is not null) then raise exception 'Reviewer cannot see signature';end if;
 if not exists(select 1 from public.notifications where observation_id=obs and user_id=supervisor and title like 'Signature added%') then raise exception 'Signature notification missing';end if;
 ctx:=public.record_signature_context('observation',obs);sig2:=public.add_record_signature('observation',obs,supervisor,ctx->>'snapshot_hash',draw,'Reviewed record',gen_random_uuid(),true);
 perform pg_temp.qa_change_signature_observation(obs);
 bad:=false;begin perform public.add_record_signature('observation',obs,supervisor,hash,draw,'Stale version',gen_random_uuid(),true);exception when raise_exception then bad:=true;end;if not bad then raise exception 'Signature accepted stale observation';end if;
 if (select snapshot from public.record_signatures where id=sig) is distinct from old_snapshot then raise exception 'Old signed evidence was rewritten';end if;
 ctx:=public.record_signature_context('observation',obs);if (ctx->>'already_signed')::boolean then raise exception 'Edited record claims current signature';end if;
 perform public.add_record_signature('observation',obs,supervisor,ctx->>'snapshot_hash',draw,'Reviewed new version',gen_random_uuid(),true);
 -- Read-only corporate access does not confer the ability to sign on participants\' behalf.
 perform set_config('request.jwt.claim.sub',ceo::text,true);ctx:=public.record_signature_context('observation',obs);
 if (ctx->>'can_sign')::boolean then raise exception 'Unaddressed corporate reader can sign';end if;
 bad:=false;begin perform public.add_record_signature('observation',obs,ceo,ctx->>'snapshot_hash',draw,'Unauthorized',gen_random_uuid(),true);exception when raise_exception then bad:=true;end;if not bad then raise exception 'Nonparticipant signature accepted';end if;
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 task:=public.create_operation_task(jsonb_build_object('title','[QA rollback] Signature task','description','Inspect reported vibration','assigned_to',op,'business_unit_id',unit,'due_at',now()+interval '1 day','checklist',jsonb_build_array(jsonb_build_object('label','Check evidence','required',true))));
 perform set_config('request.jwt.claim.sub',op::text,true);ctx:=public.record_signature_context('task',task);hash:=ctx->>'snapshot_hash';
 select status,last_activity_id into before_status,before_activity from public.operation_tasks where id=task;
 sig:=public.add_record_signature('task',task,op,hash,draw,'Instructions acknowledged',gen_random_uuid(),true);
 if (select status from public.operation_tasks where id=task) is distinct from before_status or (select progress from public.operation_tasks where id=task)<>0 or (select last_activity_id from public.operation_tasks where id=task)<>before_activity then raise exception 'Signature changed task workflow or invalidated pending progress';end if;
 if jsonb_array_length((select snapshot->'checklist' from public.record_signatures where id=sig))<>1 then raise exception 'Checklist absent from signed record';end if;
 perform public.send_operation_task_message(task,'Chat is not signed record content',gen_random_uuid());ctx:=public.record_signature_context('task',task);
 if ctx->>'snapshot_hash' is distinct from hash then raise exception 'Chat changed signed record hash';end if;
 perform public.update_operation_task(task,'Actual progress after signature',15,'in_progress','[]',before_activity);ctx:=public.record_signature_context('task',task);
 if ctx->>'snapshot_hash'=hash then raise exception 'Progress did not change signed record version';end if;
 bad:=false;begin perform public.add_record_signature('task',task,op,hash,draw,'Stale progress',gen_random_uuid(),true);exception when raise_exception then bad:=true;end;if not bad then raise exception 'Stale task signature accepted';end if;
 bad:=false;begin update public.record_signatures set signer_name='Forged' where id=sig;exception when insufficient_privilege then bad:=true;end;if not bad then raise exception 'Client can rewrite signature';end if;
 bad:=false;begin delete from public.record_signatures where id=sig;exception when insufficient_privilege then bad:=true;end;if not bad then raise exception 'Client can erase signature';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 if exists(select 1 from public.record_signatures where observation_id=obs or task_id=task) then raise exception 'Unrelated operator reads signatures';end if;
 bad:=false;begin perform public.record_signature_context('task',task);exception when raise_exception then bad:=true;end;if not bad then raise exception 'Signature context leaked private record';end if;
end $$;
set local role anon;
do $$begin if has_table_privilege('anon','public.record_signatures','select') or has_function_privilege('anon','public.record_signature_context(text,uuid)','execute') or has_function_privilege('anon','public.add_record_signature(text,uuid,uuid,text,jsonb,text,uuid,boolean)','execute') then raise exception 'Anonymous signature access';end if;end$$;
reset role;
select 'optional_record_signatures_passed' result;
rollback;
